template <typename T>
void GetBoundingBoxOfTriangle(real3<T> *bmin, real3<T> *bmax, const T *vertices, const unsigned int *faces, unsigned int index) {
    // Fetch the three vertex indices for the triangle
    unsigned int i0 = faces[3 * index + 0];
    unsigned int i1 = faces[3 * index + 1];
    unsigned int i2 = faces[3 * index + 2];

    // Retrieve the vertices
    const T *v0 = &vertices[3 * i0];
    const T *v1 = &vertices[3 * i1];
    const T *v2 = &vertices[3 * i2];

    // Initialize bmin and bmax with the first vertex
    (*bmin).v[0] = v0[0];
    (*bmin).v[1] = v0[1];
    (*bmin).v[2] = v0[2];
    (*bmax).v[0] = v0[0];
    (*bmax).v[1] = v0[1];
    (*bmax).v[2] = v0[2];

    // Expand the bounding box to include v1 and v2
    for (int i = 0; i < 3; ++i) {
        (*bmin).v[i] = std::min((*bmin).v[i], v1[i]);
        (*bmin).v[i] = std::min((*bmin).v[i], v2[i]);
        (*bmax).v[i] = std::max((*bmax).v[i], v1[i]);
        (*bmax).v[i] = std::max((*bmax).v[i], v2[i]);
    }
}

